236:/// Whether a field should be sorted case-sensitively or case-insensitively.
237:/// This determines which of the `natord` functions to use.
238:///
239:/// I kept on forgetting which one was sensitive and which one was
240:/// insensitive. Would a case-sensitive sort put capital letters first because
241:/// it takes the case of the letters into account, or intermingle them with
242:/// lowercase letters because it takes the difference between the two cases
243:/// into account? I gave up and just named these two variants after the
244:/// effects they have.
245:#[derive(PartialEq, Eq, Debug, Copy, Clone)]
246:pub enum SortCase {
247:    /// Sort files case-sensitively with uppercase first, with ‘A’ coming
248:    /// before ‘a’.
249:    ABCabc,
250:
251:    /// Sort files case-insensitively, with ‘A’ being equal to ‘a’.
252:    AaBbCc,
253:}
254:
255:impl SortField {
256:    /// Compares two files to determine the order they should be listed in,
257:    /// depending on the search field.
258:    ///
259:    /// The `natord` crate is used here to provide a more *natural* sorting
260:    /// order than just sorting character-by-character. This splits filenames
261:    /// into groups between letters and numbers, and then sorts those blocks
262:    /// together, so `file10` will sort after `file9`, instead of before it
263:    /// because of the `1`.
264:    pub fn compare_files(self, a: &File<'_>, b: &File<'_>) -> Ordering {
265:        use self::SortCase::{ABCabc, AaBbCc};
266:
267:        #[rustfmt::skip]
268:        return match self {
269:            Self::Unsorted  => Ordering::Equal,
270:
271:            Self::Name(ABCabc)  => natord::compare(&a.name, &b.name),
272:            Self::Name(AaBbCc)  => natord::compare_ignore_case(&a.name, &b.name),
273:
274:            Self::Size          => a.length().cmp(&b.length()),
275:
276:            #[cfg(unix)]
277:            Self::FileInode     => {
278:                a.metadata().map_or(0, MetadataExt::ino)
279:                    .cmp(&b.metadata().map_or(0, MetadataExt::ino))
280:            }
281:            Self::ModifiedDate  => a.modified_time().cmp(&b.modified_time()),
282:            Self::AccessedDate  => a.accessed_time().cmp(&b.accessed_time()),
283:            Self::ChangedDate   => a.changed_time().cmp(&b.changed_time()),
284:            Self::CreatedDate   => a.created_time().cmp(&b.created_time()),
285:            Self::ModifiedAge   => b.modified_time().cmp(&a.modified_time()),  // flip b and a
286:            Self::FileType => match a.type_char().cmp(&b.type_char()) { // todo: this recomputes
287:                Ordering::Equal  => natord::compare(&a.name, &b.name),
288:                order            => order,
289:            },
290:
291:            Self::Extension(ABCabc) => match a.ext.cmp(&b.ext) {
292:                Ordering::Equal  => natord::compare(&a.name, &b.name),
293:                order            => order,
294:            },
295:
296:            Self::Extension(AaBbCc) => match a.ext.cmp(&b.ext) {
297:                Ordering::Equal  => natord::compare_ignore_case(&a.name, &b.name),
298:                order            => order,
299:            },
300:
301:            Self::NameMixHidden(ABCabc) => natord::compare(
302:                Self::strip_dot(&a.name),
303:                Self::strip_dot(&b.name)
304:            ),
305:            Self::NameMixHidden(AaBbCc) => natord::compare_ignore_case(
306:                Self::strip_dot(&a.name),
307:                Self::strip_dot(&b.name)
308:            ),
309:        };
310:    }
311:
312:    fn strip_dot(n: &str) -> &str {
313:        match n.strip_prefix('.') {
314:            Some(s) => s,
315:            None => n,
316:        }
317:    }
318:}
